package com.aetherforge.service;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import java.util.*;
@Service public class SimulatorService {private final JdbcTemplate db;private final EventStreamService stream;private int tick=0;public SimulatorService(JdbcTemplate db,EventStreamService stream){this.db=db;this.stream=stream;}@Scheduled(fixedDelay=5000,initialDelay=8000)public void tick(){tick++;var id=db.query("select id from machine where code='M-07'",rs->{rs.next();return rs.getString(1);});double phase=Math.min(1.0,(tick%120)/120.0);double vib=2.8+phase*2.6;double temp=59+phase*13;double health=Math.max(48,84-phase*36);double risk=Math.min(.97,.58+phase*.36);db.update("update machine set health=?,failure_probability=?,rul_hours=?,status=? where id::text=?",health,risk,Math.max(40,780-phase*720),health<60?"CRITICAL":"WARNING",id);db.update("insert into sensor_reading(sensor_id,recorded_at,value) select s.id,now(),case when s.kind='Vibration' then ? when s.kind='Temperature' then ? else value end from sensor s join lateral (select value from sensor_reading sr where sr.sensor_id=s.id order by recorded_at desc limit 1) sr on true where s.machine_id::text=?",vib,temp,id);db.update("insert into anomaly(machine_id,sensor_kind,score,description,detected_at) values(?,'Vibration',?,'Correlated bearing degradation signal in simulation',now())",id,Math.min(.99,.62+phase*.25));db.update("insert into failure_prediction(machine_id,health_score,anomaly_score,failure_probability,rul_hours,risk_level,predicted_at,model_version,explanation) values(?,?,?,?,?,?,now(),'aetherforge-synthetic-v1',?)",id,health,Math.min(.99,.62+phase*.25),risk,Math.max(40,780-phase*720),risk>.7?"CRITICAL":"HIGH","CNC-07 is in DEMO/SIMULATION degradation mode; vibration and temperature are trending upward.");if(risk>.72){db.update("insert into alert(factory_id,machine_id,severity,status,description,evidence,recommendation) select factory_id,id,'CRITICAL','OPEN','CNC-07 simulated bearing risk crossed threshold','Vibration and temperature trend exceed baseline','Schedule bearing inspection.' from machine where id::text=? and not exists(select 1 from alert where machine_id=machine.id and status='OPEN' and created_at>now()-interval '30 minutes')",id);}if(tick%6==0)stream.emit(Map.of("type","MACHINE_UPDATE","machineId",id,"health",health,"failureProbability",risk,"vibration",vib,"temperature",temp,"timestamp",System.currentTimeMillis()));}}
